for name, data in results.items():
    u, p = mannwhitneyu(data["lfb"], data["cma"], alternative="two-sided")
    lfb_mean = np.mean(data["lfb"])
    cma_mean = np.mean(data["cma"])
    print(f"{name}: U={u:.3f}, p={p:.4e}, lfb_mean={lfb_mean:.5f}, cma_mean={cma_mean:.5f}")

for name, data in results.items():
    u, p = mannwhitneyu(data["lfb"], data["openai"], alternative="two-sided")
    lfb_mean = np.mean(data["lfb"])
    openai_mean = np.mean(data["openai"])
    print(f"{name}: U={u:.3f}, p={p:.4e}, lfb_mean={lfb_mean:.5f}, openai_mean={openai_mean:.5f}")
